code.cpp:
class Solution {
public:
    vector<int> successfulPairs(vector<int>& spells, vector<int>& potions, long long success) {
        int n = spells.size();
        int m = potions.size();
        sort(potions.begin(), potions.end());
        vector<int> pairs(n);
        for (int i = 0; i < n; i++) {
            long long spell = spells[i];
            int lo = 0, hi = m;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (spell * (long long)potions[mid] >= success) {
                    hi = mid;
                } else {
                    lo = mid + 1;
                }
            }
            pairs[i] = m - lo;
        }
        return pairs;
    }
};
